import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import 'package:url_launcher/url_launcher.dart';
import '../config.dart';
import '../data/store.dart';
import '../l10n/strings.dart';
import 'shell.dart';
import 'theme.dart';
class SettingsScreen extends StatelessWidget {
  final UpcStore store;
  const SettingsScreen(this.store,{super.key});
  Future<String?> input(BuildContext context,String label,String initial,{bool secret=false})async{final c=TextEditingController(text:initial);final result=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:Text(label),content:TextField(controller:c,obscureText:secret,decoration:InputDecoration(labelText:label)),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text(Strings.of(ctx)['cancel'])),TextButton(onPressed:()=>Navigator.pop(ctx,c.text),child:Text(Strings.of(ctx)['confirm']))]));c.dispose();return result;}
  Future<void> notice(BuildContext context,String title,String body)async{await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(title),content:Text(body),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('OK'))]));}
  @override Widget build(BuildContext context){final s=Strings.of(context);final tiles=<({String key,IconData icon,Color color,VoidCallback action})>[
    (key:'profile',icon:Icons.person_outline,color:blue,action:()=>profile(context)),
    (key:'language',icon:Icons.language,color:green,action:()=>languages(context)),
    (key:'currency',icon:Icons.currency_exchange,color:green,action:()=>fx(context)),
    (key:'appearance',icon:Icons.palette_outlined,color:Colors.purple,action:()=>appearance(context)),
    (key:'notifications',icon:Icons.notifications_outlined,color:Colors.pink,action:()=>notifications(context)),
    (key:'sync',icon:Icons.cloud_sync_outlined,color:blue,action:()=>runAction(context,()async{await store.refresh();if(store.error!=null){throw StateError(store.error!);}})),
    (key:'security',icon:Icons.shield_outlined,color:navy,action:()=>security(context)),
    (key:'premium',icon:Icons.workspace_premium_outlined,color:gold,action:()=>premium(context)),
    (key:'help',icon:Icons.help_outline,color:blue,action:()=>notice(context,s['help'],'Use complete per-room nightly rate plans. Missing dates must be priced manually. Save creates an immutable archive record; use Duplicate to start a new editable draft.')),
    (key:'feedback',icon:Icons.chat_bubble_outline,color:blue,action:()=>feedback(context)),
    (key:'about',icon:Icons.info_outline,color:blue,action:()=>notice(context,'UPC','Umrah Package Calculator\nVersion 1.0.0\nUPC calculates package costs. It does not book or sell hotel rooms.\nFX source: open.er-api.com (USD base).')),
    (key:'logout',icon:Icons.logout,color:Colors.red,action:()=>runAction(context,()async{await store.persistDraft();await store.client.auth.signOut();}))
  ];return ListView(padding:const EdgeInsets.all(10),children:[Panel(child:Column(children:tiles.map((t)=>ListTile(dense:true,contentPadding:const EdgeInsets.symmetric(horizontal:3),leading:CircleAvatar(radius:14,backgroundColor:t.color,child:Icon(t.icon,color:Colors.white,size:17)),title:Text(s[t.key]),trailing:const Icon(Icons.chevron_right,size:18),onTap:t.action)).toList())),if(store.error!=null)Text(store.error!,style:const TextStyle(color:Colors.red,fontSize:12))]);}
  Future<void> profile(BuildContext context)async{await runAction(context,()async{final old=store.client.auth.currentUser?.userMetadata??{};final name=await input(context,Strings.of(context)['fullName'],old['full_name'] as String? ?? '');if(name!=null){await store.client.auth.updateUser(UserAttributes(data:{'full_name':name}));}});}
  Future<void> languages(BuildContext context)async{final code=await showDialog<String>(context:context,builder:(ctx)=>SimpleDialog(title:Text(Strings.of(ctx)['language']),children:[for(final pair in {'en':'English','uz':'O‘zbekcha','ar':'العربية'}.entries)SimpleDialogOption(onPressed:()=>Navigator.pop(ctx,pair.key),child:Text(pair.value)),const Padding(padding:EdgeInsets.all(12),child:Text('18 additional required languages remain incomplete. See DELIVERY_STATUS.md.',style:TextStyle(fontSize:12,color:Colors.red)))]));if(code!=null&&context.mounted){await runAction(context,()=>store.setSetting('language',code));}}
  Future<void> appearance(BuildContext context)async{final mode=await showDialog<String>(context:context,builder:(ctx)=>SimpleDialog(title:Text(Strings.of(ctx)['appearance']),children:[for(final mode in ['system','light','dark'])SimpleDialogOption(onPressed:()=>Navigator.pop(ctx,mode),child:Text(mode))]));if(mode!=null&&context.mounted){await runAction(context,()=>store.setSetting('appearance',mode));}}
  Future<void> fx(BuildContext context)async{final s=Strings.of(context);await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(s['currency']),content:Column(mainAxisSize:MainAxisSize.min,children:[Text('${s['fxLabel']}: ${store.draft.fx??s['unavailable']}'),Text(store.draft.fxManual?s['manualFx']:s['auto']),TextButton(onPressed:()async{final value=await input(ctx,s['fxLabel'],store.draft.fx?.toString()??'');if(value==null){return;}final rate=double.tryParse(value);if(rate==null||!rate.isFinite||rate<=0){if(ctx.mounted){await notice(ctx,'Invalid rate','Enter a positive exchange rate.');}return;}await store.manualFx(rate);if(ctx.mounted){Navigator.pop(ctx);}},child:Text(s['manualFx'])),TextButton(onPressed:()async{await store.resetFx();if(ctx.mounted){Navigator.pop(ctx);}},child:Text(s['resetFx'])),const Text('FX: ExchangeRate-API open endpoint. Cache valid for 24 hours.',style:TextStyle(fontSize:12))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('OK'))]));}
  Future<void> notifications(BuildContext context)async{await showDialog<void>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:Text(Strings.of(ctx)['notifications']),content:Column(mainAxisSize:MainAxisSize.min,children:[const Text('Push delivery is not connected in this source release. Preferences are persisted; this does not enable delivery.'),for(final key in ['premium_alerts','announcements','haramain_promotions'])SwitchListTile(title:Text(key),value:store.settings[key] as bool? ?? false,onChanged:(v)=>runAction(ctx,()async{await store.setSetting(key,v);set((){});}))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('OK'))])));}
  Future<void> premium(BuildContext context)async{final a=store.account;await notice(context,Strings.of(context)['premium'],'Trial ends: ${a['trial_ends_at']??'—'}\nPremium expires: ${a['premium_until']??'—'}\nPermanent: ${a['permanent']??false}\n\nStore checkout and receipt verification are not connected. No purchase can be made in this source release. Intended plans require approved Google/Apple product configuration.');}
  Future<void> security(BuildContext context)async{await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(Strings.of(ctx)['security']),content:Column(mainAxisSize:MainAxisSize.min,children:[TextButton(onPressed:()=>runAction(ctx,()async{final password=await input(ctx,Strings.of(ctx)['password'],'',secret:true);if(password!=null){await store.client.auth.updateUser(UserAttributes(password:password));}}),child:const Text('Change password')),TextButton(onPressed:()=>runAction(ctx,()=>store.client.auth.signOut(scope:SignOutScope.others)),child:const Text('Sign out other devices')),TextButton(onPressed:()=>runAction(ctx,()async{final devices=await store.client.from('devices').select().eq('user_id',store.uid);if(ctx.mounted){await notice(ctx,'Devices',devices.isEmpty?'Device registration is not yet implemented.':devices.toString());}}),child:const Text('Active devices')),TextButton(onPressed:()=>runAction(ctx,()async{if(await askConfirm(ctx,'Permanently delete your account and private data?')){await store.client.functions.invoke('delete-account');await store.prefs.remove(store.key);await store.client.auth.signOut();if(ctx.mounted){Navigator.pop(ctx);}}}),child:const Text('Delete Account',style:TextStyle(color:Colors.red))),const Text('Private hotels, drafts and archives are isolated by account. Administrators cannot browse private calculation contents. Production privacy/legal text is still required.',style:TextStyle(fontSize:12))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('OK'))]));}
  Future<void> feedback(BuildContext context)async{final email=store.appSettings['support_email'] as String? ?? Config.supportEmail,phone=store.appSettings['support_phone'] as String? ?? Config.supportPhone;await showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:Text(Strings.of(ctx)['feedback']),content:Column(mainAxisSize:MainAxisSize.min,children:[for(final kind in ['Suggestion / Feedback','Report a Problem','Other Message'])ListTile(title:Text(kind),onTap:()=>runAction(ctx,()async{final text=await input(ctx,kind,'');if(text!=null&&text.trim().isNotEmpty){await store.client.from('feedback').insert({'user_id':store.uid,'kind':kind,'body':text});}})),if(email.isNotEmpty)ListTile(leading:const Icon(Icons.email_outlined),title:Text(email),onTap:()=>launchUrl(Uri(scheme:'mailto',path:email))),if(phone.isNotEmpty)ListTile(leading:const Icon(Icons.phone_outlined),title:Text(phone),onTap:()=>launchUrl(Uri(scheme:'tel',path:phone))),if(email.isEmpty&&phone.isEmpty)const Text('Owner support contacts are not configured.')]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('OK'))]));}
}
